            raise InvalidInput("frame too long")
        # 正文无符号 zlib.crc32 的 4 字节小端值作为 FCS
        fcs = (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little")
        results.append(
            {"t": t, "port": port, "length": length, "data": (body + fcs).hex()}
        )
    return {"results": results}


